J('stellvertretende-filialleitung', 'handel', 'Stellvertretende Filialleitung',
  'stellvertretende filialleitung stellvertretender filialleiter erstkraft marktleitung stellvertretung einzelhandel bewerbung',
  'Der nächste Schritt nach dem Verkauf – Verantwortung im Markt.',
  'Bewerbung als stellvertretende Filialleitung im Einzelhandel: Muster-Anschreiben für Erstkraft, Kaufmann im Einzelhandel und Wechslerin aus der Gastronomie, mit Lebenslauf.',
  'Als Stellvertretung der Filialleitung bist du für Schichtpläne, Warenfluss, Kasse und Team mitverantwortlich und leitest den Laden, wenn die Chefin nicht da ist. Unternehmen suchen Leute, die schon im Verkauf Verantwortung übernommen haben und mit Kennzahlen umgehen können.',
  ['Abgeschlossene Ausbildung im Handel oder Erfahrung', 'Erste Führungserfahrung (Erstkraft, Azubis)', 'Kennzahlen: Umsatz, Inventur, Personal', 'Belastbarkeit und Flexibilität', 'Freundlicher, klarer Ton im Team'],
  [L('Erstkraft im Drogeriemarkt', 'erfahren', 'Stellvertretende Filialleiterin',
     T('Drogeriemarkt am Kennedyplatz', 'm', 'Lehmann', 'Bahnhofstraße 15', '45127 Essen'),
     ['wenn unsere Filialleiterin im Urlaub ist, führe ich die Filiale mit neun Mitarbeitenden allein. Schichtpläne, Bestellungen, Kassenabrechnung und die Frage, wer am Samstag für die kranke Kollegin einspringt, kenne ich also schon. Jetzt möchte ich offiziell Verantwortung übernehmen.',
      'Kauffrau im Einzelhandel bin ich seit sechs Jahren, seit zwei Jahren Erstkraft. Ich betreue unsere drei Azubis und habe die letzte Inventur mit einer Differenz unter dem Bezirksdurchschnitt abgeschlossen. Der Ausbilderschein ist vorhanden.',
      'Mein Ziel ist, in einigen Jahren eine eigene Filiale zu führen.'],
     ['Lebenslauf', 'Arbeitszeugnis', 'Ausbildereignung']),
   L('Schichtleiter aus der Systemgastronomie', 'quereinstieg', 'Stellvertretender Marktleiter Lebensmittel',
     T('Frischemarkt Rüttenscheid', 'none', '', 'Rüttenscheider Straße 120', '45131 Essen'),
     ['in einem Schnellrestaurant mit 40 Mitarbeitenden habe ich vier Jahre lang Schichten geleitet, an manchen Tagen mit 800 Bestellungen. Personalplanung, Warenbestellung, Hygiene und Kassenabschluss gehören dort zum Alltag. Den Einzelhandel möchte ich als nächstes kennenlernen.',
      'Frische Ware, Kühlkette, Abschriften und Inventur sind mir aus der Gastronomie vertraut, das Sortiment eines Supermarkts lerne ich gern. Ich bin 29, habe ein Fachabitur und eine Weiterbildung zur Schichtführung.'],
     ['Lebenslauf', 'Arbeitszeugnis'],
     ['Kevin Owusu', 'Altendorfer Straße 80', '45143 Essen'])],
  CV('a06', 'classic', 1, 'Fatma Yıldız', 'Kauffrau im Einzelhandel, Erstkraft', 'Viehofer Straße 30', '45127 Essen',
     [row('2020', '', 'Verkäuferin, seit 2024 Erstkraft', 'Drogeriemarkt Essen-Mitte', 'Essen', '- Filialvertretung bei 9 Mitarbeitenden\n- Betreuung von drei Azubis\n- Bestellungen, Schichtplanung, Inventur')],
     [row('2017', '2020', 'Ausbildung Kauffrau im Einzelhandel', 'Drogeriemarkt Essen-Mitte', 'Essen', '')],
     [['Teamkoordination', 4], ['Warenwirtschaft', 4], ['Kassenabrechnung', 5], ['Azubibetreuung', 4]],
     [DE, ['Türkisch', 'native'], ['Englisch', 'B1']], 'Fitness, Kochen', courses=[row('', '2025', 'Ausbildereignungsprüfung (AEVO)', 'IHK Essen')]),
  ['Bisherige Verantwortung konkret nennen.', 'Kennzahlen (Inventur, Umsatz) einbauen.', 'Ziel Filialleitung ansprechen.'],
  ['Nur Verkaufserfahrung ohne Verantwortung.', 'Konflikte im Team ausbreiten.', 'Arbeitszeiten zu eng setzen.'],
  ['Wie gehen Sie mit einem Mitarbeiter um, der ständig zu spät kommt?', 'Wie planen Sie eine Woche mit drei Krankmeldungen?', 'Was tun Sie bei einer hohen Inventurdifferenz?', 'Wo sehen Sie sich in drei Jahren?'],
  [Q('Brauche ich den Ausbilderschein?', 'Nicht immer, aber er hilft, weil Stellvertretungen oft Azubis betreuen. Viele Händler unterstützen die Prüfung.')],
  ['filialleiter', 'kaufmann-im-einzelhandel', 'teamleiter', 'modeberater'])

